    {
      "term": {
        "text": "final variable",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "a variable declared with the final keyword that cannot be assigned a new value after its initialization, effectively making it a constant",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "constant",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "a value that does not change during program execution; in Java it is typically declared with the final keyword and named using all capital letters",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "arithmetic expression",
        "refs": ["Q0003"]
      },
      "definition_text": {
        "text": "a piece of code that combines operands and operators to produce a value",
        "refs": ["Q0003"]
      },
      "context": null
    },
    {
      "term": {
        "text": "operand",
        "refs": ["Q0004"]
      },
      "definition_text": {
        "text": "a value or variable that an operator works on within an expression",
        "refs": ["Q0004"]
      },
      "context": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "addition",
        "refs": ["Q0002"]
      },
      "example_text": {
        "text": "int result = 10 + 3; // result is 13",
        "refs": ["Q0002"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "casting to double for floating‑point division",
        "refs": ["Q0003"]
      },
      "example_text": {
        "text": "double result = (double)10 / 3; // result is 3.333…",
        "refs": ["Q0003"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "increment operator (postfix)",
        "refs": ["Q0005"]
      },
      "example_text": {
        "text": "int x = 1; x++; // x becomes 2",
        "refs": ["Q0005"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "increment operator (prefix)",
        "refs": ["Q0005"]
      },
      "example_text": {
        "text": "int x = 1; ++x; // x becomes 2",
        "refs": ["Q0005"]
      },
      "example_type": null
    }
  ],
  "explanations": [
    {
      "topic": {
        "text": "naming convention for constants",
        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "By convention, constants are named using all capital letters (e.g., PI) to distinguish them from regular variables.",
        "refs": ["Q0000"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "integer division behavior",
        "refs": ["Q0002"]
      },
      "explanation_text": {
        "text": "In Java, dividing two whole numbers yields a whole number (the fractional part is discarded).",
        "refs": ["Q0002"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "floating‑point division requirement",
        "refs": ["Q0003"]
      },
      "explanation_text": {
        "text": "To obtain a floating‑point result from division, at least one operand must be cast to a float or double.",
        "refs": ["Q0003"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "increment/decrement operators",
        "refs": ["Q0004"]
      },
      "explanation_text": {
        "text": "The ++ operator increases a variable's value by 1; it can be used as a prefix (e.g., ++x) or postfix (e.g., x++).",
        "refs": ["Q0004"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "A final variable cannot be assigned a new value after its initial assignment.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The arithmetic operators in Java are addition (+), subtraction (‑), multiplication (*), division (/), and modulus (%).",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "When an integer variable is assigned the result of a division between two integers, the result is an integer.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Casting an integer to double before division yields a floating‑point result.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    }
  ],
